const input = items[0]?.json || {};

return [
 {
   json: {
     ...input,
     m7_config: {
       service_name: 'DALIA_M7_Messaging_Service_Lite',
       service_version: 'v1',

       contracts: {
         request_schema_version: 'dalia.m3_to_m7.v1',
         result_schema_version: 'dalia.m7.delivery_result.v1'
       },

       source: {
         image_provider: 'google_drive',
         drive_root_folder_id: '1msXda2akpa8wE_Dwcd4vNdtQh-_KHMaZ',
         folder_strategy: 'category_sku_folder',
         expected_structure: '/<category>/<sku>/<image_file>'
       },

       image_policy: {
         allowed_mime_types: [
           'image/jpeg',
           'image/png',
           'image/webp'
         ],
         preferred_name_signals: [
           'principal',
           'main',
           'front',
           '1'
         ],
         max_candidate_files: 10
       },

       presentation_policy: {
         default_sequence: 'text_then_image',
         product_image_modes: [
           'single'
         ],
         allow_images_for_recommendation: false,
         allow_images_for_product_detail: true
       },

       fallback_policy: {
         image_not_found: 'image_not_found',
         category_folder_not_found: 'category_folder_not_found',
         product_folder_not_found: 'product_folder_not_found',
         invalid_image_file: 'invalid_image_file'
       },
       text_template_policy: {
         max_sentences: 4,
         max_length: 520,
         ask_one_question_at_end: true,
         forbid_sku_in_text: true,
         forbid_internal_terms: true,
         avoid_price_unless_present: true,
         avoid_stock_unless_present: true,
         default_question: '¿Quieres que te comparta más detalles?',
          fallback_question: '¿Quieres que te ayude a revisar esta opción?'
        }
     }
   }
 }


];

function clean(value) {
 if (value === null || value === undefined) return '';
 return String(value).trim();
}

function firstArrayItem(value) {
 return Array.isArray(value) && value.length > 0 ? value[0] : null;
}

const input = items[0]?.json || {};
const config = input.m7_config || {};

const trace = input.trace || {};
const channel = input.channel || {};
const message = input.message || {};
const presentation = input.presentation || {};
const catalog = input.catalog || {};
const control = input.control || {};

const firstImageCandidate = firstArrayItem(presentation.image_candidates);
const firstCatalogItem = firstArrayItem(catalog.items);

const productCandidate = firstImageCandidate || firstCatalogItem || {};

const sendImage = Boolean(presentation.sendImage);
const imageMode = clean(presentation.image_mode || 'none');
const responseType = clean(message.response_type);

let presentationMode = 'text_only';

if (
 sendImage &&
 imageMode === 'single' &&
 responseType === 'product_detail'
) {
 presentationMode = 'product_with_image';
}

if (!clean(message.replyText)) {
 presentationMode = 'invalid';
}

const normalizedProduct = {
 product_id: clean(
   productCandidate.product_id ||
   productCandidate.sku
 ),
 sku: clean(
   productCandidate.sku ||
   productCandidate.product_id
 ),
 display_name: clean(productCandidate.display_name),
 category: clean(productCandidate.category),
 color: clean(productCandidate.color)
};

return [
 {
   json: {
     ...input,
     m7_request: {
       schema_version:
         input.schema_version ||
         config.contracts?.request_schema_version ||
         'dalia.m3_to_m7.v1',

       trace: {
         event_id: clean(trace.event_id),
         conversation_id: clean(trace.conversation_id),
         session_id: clean(trace.session_id)
       },

       channel: {
         name: clean(channel.name || 'whatsapp'),
         user_id: clean(channel.user_id),
         display_name: clean(channel.display_name)
       },

       message: {
         replyText: clean(message.replyText),
         response_type: responseType,
         next_step: clean(message.next_step)
       },

       presentation: {
         sendImage,
         image_mode: imageMode,
         image_candidates: Array.isArray(presentation.image_candidates)
           ? presentation.image_candidates
           : []
       },

       product: normalizedProduct,

       catalog: {
         used_catalog: catalog.used_catalog !== false,
         matched: Boolean(catalog.matched),
         match_type: clean(catalog.match_type),
         items: Array.isArray(catalog.items) ? catalog.items : []
       },

       control: {
         can_continue: control.can_continue !== false,
         fallback_reason: clean(control.fallback_reason)
       },

       presentation_mode: presentationMode
     }
   }
 }
];

function isEmpty(value) {
 return value === null || value === undefined || String(value).trim() === '';
}

const input = items[0]?.json || {};
const request = input.m7_request || {};

// 🚨 CHEAT CODE: Forzar el modo visual si la IA pidió mandar imagen
if (request.presentation?.sendImage === true) {
 request.presentation_mode = 'product_with_image';
}

const errors = [];
const warnings = [];

if (isEmpty(request.channel?.user_id)) {
 errors.push('missing_channel_user_id');
}

if (isEmpty(request.message?.replyText)) {
 errors.push('missing_reply_text');
}

if (request.presentation_mode === 'product_with_image') {
 // 1. Relajar la regla: Permitir imágenes tanto en product_detail como en recommendation
 if (request.message?.response_type !== 'product_detail' && request.message?.response_type !== 'recommendation') {
   errors.push('image_requested_for_invalid_response_type');
 }

 // 2. El chequeo estricto de SKU único solo aplica para product_detail
 if (request.message?.response_type === 'product_detail') {
   if (isEmpty(request.product?.sku) && isEmpty(request.product?.product_id)) {
     errors.push('missing_product_sku_or_product_id');
   }
   if (isEmpty(request.product?.category)) {
     errors.push('missing_product_category');
   }
 }
}

if (
 request.presentation?.sendImage === true &&
 request.presentation_mode !== 'product_with_image'
) {
 warnings.push('send_image_requested_but_mode_not_product_with_image');
}

return [
 {
   json: {
     ...input,
     m7_validation: {
       valid: errors.length === 0,
       errors,
       warnings
     }
   }
 }
];

const input = items[0]?.json || {};

return [
 {
