function clean(value) {
 if (value === null || value === undefined) return '';
 return String(value).trim();
}

function normalize(value) {
 return clean(value)
   .toLowerCase()
   .normalize('NFD')
   .replace(/[\u0300-\u036f]/g, '');
}

const planNode = $('Normalize Product Folder Result').first().json || {};
const lookup = planNode.product_presentation_plan?.image_lookup || {};

const allowedMimeTypes = lookup.allowed_mime_types || [
 'image/jpeg',
 'image/png',
 'image/webp'
];

const preferredSignals = lookup.preferred_name_signals || [
 'principal',
 'main',
 'front',
 '1'
];

const files = items
 .map(item => item.json || {})
 .filter(file => file.id)
 .filter(file => {
   if (!file.mimeType) return true;
   return allowedMimeTypes.includes(file.mimeType);
 });

const scoredFiles = files.map(file => {
 const fileName = normalize(file.name);
 let score = 0;

 if (preferredSignals.some(signal => fileName.includes(normalize(signal)))) {
   score += 100;
 }

 if (fileName.includes(normalize(lookup.sku))) {
   score += 50;
 }

 const modifiedTime = file.modifiedTime
   ? new Date(file.modifiedTime).getTime()
   : 0;

 return {
   ...file,
   _selection_score: score,
   _modified_time_number: modifiedTime
 };
});

scoredFiles.sort((a, b) => {
 if (b._selection_score !== a._selection_score) {
   return b._selection_score - a._selection_score;
 }

 return b._modified_time_number - a._modified_time_number;
});

const selected = scoredFiles[0] || null;

const resolved = Boolean(selected?.id);

return [
 {
   json: {
     ...planNode,
     image_resolution: {
       resolved,
       source: 'google_drive',
       provider: 'google_drive',
       strategy: lookup.strategy || 'category_sku_folder',
       product_id: lookup.product_id || '',
       sku: lookup.sku || '',
