function clean(value) {
 if (value === null || value === undefined) return '';
 return String(value).trim();
}

function normalize(value) {
 return clean(value)
   .toLowerCase()
   .normalize('NFD')
   .replace(/[\u0300-\u036f]/g, '');
}

function removeInternalTerms(text) {
 return clean(text)
   .replace(/\bSKU\b/gi, '')
   .replace(/\bproduct_id\b/gi, '')
   .replace(/\bimage_ref\b/gi, '')
   .replace(/\bretrieval_score\b/gi, '')
   .replace(/\bQdrant\b/gi, '')
   .replace(/\bn8n\b/gi, '')
   .replace(/\bGoogle Drive\b/gi, '')
   .replace(/\bworkflow\b/gi, '')
   .replace(/\bmódulo\b/gi, '')
   .replace(/\bmodulo\b/gi, '')
   .replace(/\s{2,}/g, ' ')
   .trim();
}

function splitSentences(text) {
 return clean(text)
   .split(/(?<=[.!?])\s+/)
   .map(sentence => sentence.trim())
   .filter(Boolean);
}

function limitSentences(text, maxSentences) {
 const sentences = splitSentences(text);
 if (sentences.length <= maxSentences) return clean(text);
 return sentences.slice(0, maxSentences).join(' ');
}

function limitLength(text, maxLength) {
 const cleanText = clean(text);
 if (cleanText.length <= maxLength) return cleanText;
 return cleanText.slice(0, maxLength).replace(/\s+\S*$/, '').trim() + '.';
}

function hasQuestionAtEnd(text) {
 return /[?？]\s*$/.test(clean(text));
}

function ensureQuestionAtEnd(text, question) {
 const cleanText = clean(text);

 if (!cleanText) return question;
 if (hasQuestionAtEnd(cleanText)) return cleanText;

 return `${cleanText} ${question}`;
}

function firstSentence(value) {
 const sentences = splitSentences(value);
 return sentences[0] || '';
}

function buildTemplateFromProduct(product, request, policy) {
 const productName = clean(product.display_name) || 'este producto';
 const category = clean(product.category);
 const color = clean(product.color);
 const description = clean(product.description_short);

 const benefit = firstSentence(description);

 let text = `Te muestro ${productName}.`;

 if (benefit) {
   text += ` ${benefit}.`;
 } else if (category) {
   text += ` Es una opción de la categoría ${category}.`;
 }

 if (color) {
   text += ` En esta referencia lo tengo identificado en color ${color}.`;
 }

 text = ensureQuestionAtEnd(
   text,
   policy.default_question || '¿Quieres que te comparta más detalles?'
 );

 return text;
}

function isTextUsable(text, policy) {
 const value = clean(text);
 if (!value) return false;

 const normalized = normalize(value);

 const forbidden = [
   'sku',
   'product_id',
   'image_ref',
   'retrieval_score',
   'qdrant',
   'n8n',
   'google drive',
   'workflow',
   'modulo',
   'módulo'
 ];

 if (forbidden.some(term => normalized.includes(normalize(term)))) {
   return false;
 }

 if (value.length > Number(policy.max_length || 520)) {
   return false;
 }

 return true;
}

