function clean(value) {
 if (value === null || value === undefined) return '';
 return String(value).trim();
}

function normalize(value) {
 return clean(value)
   .toLowerCase()
   .normalize('NFD')
   .replace(/[\u0300-\u036f]/g, '');
}

function includesAny(text, terms) {
 const normalized = normalize(text);
 return terms.some(term => normalized.includes(normalize(term)));
}

const input = items[0]?.json || {};
let text = clean(input.whatsapp_text_message?.text);

const violations = [];

if (!text) {
 violations.push('empty_fallback_text');
}

if (text.length > 520) {
 violations.push('fallback_text_too_long');
}

const forbiddenTerms = [
 'sku',
 'product_id',
 'image_ref',
 'google drive',
 'n8n',
 'workflow',
 'módulo',
 'modulo',
 'archivo',
 'carpeta',
 'error técnico'
];

if (includesAny(text, forbiddenTerms)) {
 violations.push('forbidden_internal_or_technical_term');
}

if (!/[?？]\s*$/.test(text)) {
 violations.push('missing_final_question');
}

if (violations.length > 0) {
 const productName =
   input.image_fallback_text?.display_name ||
   input.m7_request?.product?.display_name ||
   'esta opción';

 text = `Puedo ayudarte con ${productName}. Por ahora no tengo una imagen disponible para mostrarte. ¿Quieres que te comparta sus características?`;
}

return [
 {
   json: {
     ...input,
     image_fallback_text_validation: {
       valid: violations.length === 0,
       violations,
       fallback_text_rebuilt: violations.length > 0
     },
     whatsapp_text_message: {
       ...(input.whatsapp_text_message || {}),
       ready: true,
       text,
       sequence_order: 1
     }
   }
 }
];

